INSERT INTO products (id, title, jenjang, mapel, price, strikethrough_price, pages, cover_label, cover_color, badge, active, category, description, external_url, created_at) VALUES
  ('sas-mi-k1-s1', 'Paket SAS MI Kelas 1 Semester 1', 'MI', 'Mapel MI', 15000, 25000, 12, 'SAS MI 1', '#177245', 'BARU', 1, 'MI', 'Paket latihan SAS MI Kelas 1 Semester 1 untuk Al-Quran Hadis, Akidah Akhlak, Fikih, dan Bahasa Arab. Tersedia Paket 1-3 dalam PDF siap cetak serta DOCX yang dapat diedit.', 'https://drive.google.com/drive/folders/13Ak_jGYUeRvAttMlTiq_GeDTfC8Y36Lw', datetime('now')),
  ('sas-mi-k2-s1', 'Latihan Soal SAS Kelas 2 MI Semester Ganjil - 4 Mapel (PDF & Word)', 'MI', 'Mapel MI', 15000, 25000, 12, 'SAS MI 2', '#2273d8', 'BARU', 1, 'MI', 'Latihan SAS Kelas 2 MI Semester Ganjil. Dampingi anak berlatih membaca soal dan mengenali materi dasar MI menjelang Sumatif Akhir Semester (SAS) ganjil. Tersedia 12 paket berisi 300 butir untuk Al-Quran Hadis, Akidah Akhlak, Fikih, dan Bahasa Arab. Setiap paket berisi 25 soal, 15 stimulus visual, naskah murid A4 lanskap dan potret (PDF siap cetak dan Word editabel), kisi-kisi, serta kunci jawaban dan pembahasan. Disusun mengacu pada Capaian Pembelajaran Fase A dan Buku Teks Utama Kemenag.', 'https://drive.google.com/drive/folders/1MHlOJTujyC_d-lDsyWxj5a80d8nAGcor', datetime('now')),
  ('sas-mi-k3-s1', 'Latihan Soal SAS Kelas 3 MI Semester Ganjil - 5 Mapel (PDF & Word)', 'MI', 'Mapel MI', 15000, 25000, 15, 'SAS MI 3', '#159a68', 'BARU', 1, 'MI', 'Latihan SAS Kelas 3 MI Semester Ganjil untuk Al-Quran Hadis, Akidah Akhlak, Fikih, Bahasa Arab, dan SKI. Tersedia 15 paket berisi 450 butir, dengan tiga paket setiap mapel. Materi mencakup kalkalah, hikmah surah pendek, keringanan salat, kosakata Arab bergambar, dan kisah masa kecil Rasulullah. Setiap paket berisi 30 soal, 15 stimulus visual, naskah murid A4 lanskap dan potret (PDF siap cetak dan Word editabel), kisi-kisi, serta kunci jawaban dan pembahasan. Disusun mengacu pada Capaian Pembelajaran Fase B dan Buku Teks Utama Kemenag.', 'https://drive.google.com/drive/folders/1s6tv_s8Gww37A1joDB04HtEtQtwA833j', datetime('now')),
  ('sas-mi-k4-s1', 'Latihan Soal SAS Kelas 4 MI Semester Ganjil - 5 Mapel (PDF & Word)', 'MI', 'Mapel MI', 15000, 25000, 15, 'SAS MI 4', '#f2b33d', 'BARU', 1, 'MI', 'Latihan SAS Kelas 4 MI Semester Ganjil untuk Al-Quran Hadis, Akidah Akhlak, Fikih, Bahasa Arab, dan SKI. Tersedia 15 paket berisi 450 butir, dengan tiga paket setiap mapel. Materi meliputi izhar dan ikhfa, perilaku terpuji, salat Jumat, alamat dan profesi dalam Bahasa Arab, serta keteladanan Rasulullah. Setiap paket berisi 30 soal, 15 stimulus visual, naskah murid A4 lanskap dan potret (PDF siap cetak dan Word editabel), kisi-kisi, serta kunci jawaban dan pembahasan. Disusun mengacu pada Capaian Pembelajaran Fase B dan Buku Teks Utama Kemenag.', 'https://drive.google.com/drive/folders/1JboqnFj-eZHDByTP51CNYIgSOfDVHhNz', datetime('now')),
  ('sas-mi-k5-s1', 'Latihan Soal SAS Kelas 5 MI Semester Ganjil - 5 Mapel (PDF & Word)', 'MI', 'Mapel MI', 15000, 25000, 15, 'SAS MI 5', '#7c5cbf', 'BARU', 1, 'MI', 'Latihan SAS Kelas 5 MI Semester Ganjil untuk Al-Quran Hadis, Akidah Akhlak, Fikih, Bahasa Arab, dan SKI. Tersedia 15 paket berisi 450 butir, dengan tiga paket setiap mapel. Materi meliputi hukum mim sukun, zakat fitrah, infak, sedekah, persaudaraan dan perdamaian dalam sejarah Islam. Setiap paket berisi 30 soal, 15 stimulus visual, naskah murid A4 lanskap dan potret (PDF siap cetak dan Word editabel), kisi-kisi, serta kunci jawaban dan pembahasan. Disusun mengacu pada Capaian Pembelajaran Fase C dan Buku Teks Utama Kemenag.', 'https://drive.google.com/drive/folders/1E8odrfaAtssx-UzubZNzVRUKZGnUbuTg', datetime('now')),
  ('sas-mi-k6-s1', 'Latihan Soal SAS Kelas 6 MI Semester Ganjil - 5 Mapel (PDF & Word)', 'MI', 'Mapel MI', 15000, 25000, 15, 'SAS MI 6', '#e05252', 'BARU', 1, 'MI', 'Latihan SAS Kelas 6 MI Semester Ganjil untuk Al-Quran Hadis, Akidah Akhlak, Fikih, Bahasa Arab, dan SKI. Tersedia 15 paket berisi 450 butir, dengan tiga paket setiap mapel. Materi meliputi membaca jam dalam Bahasa Arab, makanan dan minuman halal, kejujuran jual beli, serta keteladanan Wali Sanga. Setiap paket berisi 30 soal, 15 stimulus visual, naskah murid A4 lanskap dan potret (PDF siap cetak dan Word editabel), kisi-kisi, serta kunci jawaban dan pembahasan. Disusun mengacu pada Capaian Pembelajaran Fase C dan Buku Teks Utama Kemenag.', 'https://drive.google.com/drive/folders/1XZXDoWgnIa5mZs7fOjdARFoZPuowKIEN', datetime('now'))
